local aq=(Rp[_p].tk or 0)-(Rp[_p-1].tk or 0)
if aq>0 then
table.insert(Xp,aq)
end
end
for bq,cq in ipairs(Rp)do
if cq.died then
table.insert(Yp,cq.died-cq.born)
end
table.insert(Zp,{cq.born,1})
table.insert(Zp,{cq.died or cq.last or cq.born,-1})
end
table.sort(Zp,function(dq,eq)
return dq[1]<eq[1]
end)
local fq,gq=0,0
for hq,iq in ipairs(Zp)do
fq=fq+iq[2]
gq=math.max(gq,fq)
end
local jq=Yo(Yp)
return{seen=true,nums={everySeen=Yo(Xp),lifeSeen=jq and math.floor(jq+0.5)or nil,capSeen=gq,made= #Rp},why=string.format(VBe[2589],#Rp)}
end
if So.family==VBe[2362]then
local kq,lq
for mq,nq in pairs(Qo.own)do
if(nq.by[Ro]or 0)>0 and nq.first>=Uo-1 and(not kq or(Vo[mq]and not Vo[kq]))then
kq,lq=mq,nq
end
end
local oq
for pq,qq in ipairs(Qo.transforms)do
if qq.from==Ro then
oq=qq.to
end
end
if not kq then
local rq,sq,tq
for uq,vq in pairs(Qo.copies)do
if vq.id==Ro or(oq and vq.id==oq)then
for wq,xq in pairs(vq.stat or{})do
if xq.hi>xq.lo and(not rq or(xq.hi-xq.lo)>(tq-sq))then
rq,sq,tq=wq,xq.lo,xq.hi
end
end
end
end
if not rq then
return{why=VBe[2590]}
end
return{seen=true,nums={stat=rq,loSeen=sq,hiSeen=tq,transformTo=oq},why=string.format(VBe[2591],rq,tostring(sq),tostring(tq))}
end
return{seen=true,buff=kq,nums={maxSeen=lq.max,steps= #lq.vals,transformTo=oq},why=string.format(VBe[2592],kq,tostring(lq.max))}
end
if So.family==VBe[2359]then
local yq,zq,Aq={},{},nil
for Bq,Cq in ipairs(Qo.steps)do
