Oq[Lq.pid]={family=Lq.family,name=Lq.name,nums=Qq,buff=Nq.buff or(Pq and Pq.buff),who=Nq.who or Lq.who,trigger=Lq.trigger,keyword=Lq.keyword,sure=(Vq and(tonumber(Pq.runs)or 0)>=1)and VBe[2539]or VBe[2597],runs=(Vq and(tonumber(Pq.runs)or 0)or 0)+1,at=os.time(),why=Nq.why}
P.pasBook[Hq]=Oq
