function pb.model(Lr,Mr,Nr)
local Or=tostring(Lr)..VBe[2302]..tostring(Nr and Nr.atk)..VBe[2302]..tostring(Nr and Nr.cd)
local Pr=pb._model[Or]
if Pr~=nil then
return Pr or nil
end
local Qr,Rr={},false
local Sr=math.max(0.3,tonumber(Nr and Nr.cd)or 2)
local Tr=math.min(1,(tonumber(Mr and Mr.n)or 1)/4)
