if ns then
ks.dmg=math.max(ks.dmg or 0,ns*js)
end
if cs.crit then
ks.crit=math.max(ks.crit or 0,(tonumber(cs.crit)or 0)*js)
end
Qr.aura,Rr=ks,true
elseif bs.family==VBe[2358]then
local ps=pb.KW[tostring(bs.keyword or VBe[1088])]
local qs=tonumber(cs.chance)or 1
local rs=tonumber(cs.secsSeen)or tonumber(cs.secs)or 5
local ss=cs.keep or cs.keepSeen
local ts=ss and math.min(1,qs*4)or math.min(1,rs*qs/Sr)
if hs then
ts=math.min(ts,rs/60)
end
if ps and ps.kind==VBe[2348]and not(type(cs.shred)==VBe[2169])then
local us=tonumber(cs.amp)
local vs=Mr and((type(Mr.ampTypes)==VBe[2169]and Mr.ampTypes[ps.dtype])or(tonumber(Mr.amp)or 0)>0)
if us and us>0 and not vs then
Qr.fx,Rr=(Qr.fx or 0)+us*V.TYPED_AMP_SHARE*ts*Tr,true
end
elseif ps and(ps.kind==VBe[2295]or ps.kind==VBe[2356])then
if not(Mr and((tonumber(Mr.stun)or 0)>0 or(tonumber(Mr.slowTime)or 0)>0))then
Qr.stun=(ps.kind==VBe[2356]and 0.5 or 1)*rs
if cs.slow then
Qr.slowP,Qr.slowT=tonumber(cs.slow),rs
end
Rr=true
end
elseif ps and ps.kind==VBe[2297]then
if not(Mr and(tonumber(Mr.slowTime)or 0)>0)then
