local oE=bb.rogueShare(VBe[2311])
lE=lE*(oE+(1-oE)/(1-kE.ice+kE.ice/gb.modFactor(VBe[2718])))
end
if kE.fly>0 then
lE=lE*(1-kE.fly*0.5)
end
if kE.noCC then
lE=lE*0.95
end
if kE.shroud then
lE=lE*0.9
end
