db.STUDY_WORDS={VBe[2264],VBe[2940],VBe[2388],VBe[2941],VBe[2942],VBe[2943],VBe[2944],VBe[2945],VBe[2946],VBe[2947],VBe[2426],VBe[2361],VBe[2297],VBe[2295],VBe[2309],VBe[2011],VBe[2009],VBe[2017],VBe[2322],VBe[2429],VBe[2948],VBe[2949],VBe[2950],VBe[2951],VBe[2952],VBe[2953],VBe[2954],VBe[2955],VBe[2956],VBe[2957],VBe[2958],VBe[2382],VBe[2959],VBe[2960]}
function db.r3(jS)
jS=tonumber(jS)
