if(kS.stun or 0)>0 then
lS.stun=db.r3(kS.stun)
end
if(kS.dot or 0)>0 then
lS.dot=db.r3(kS.dot)
end
if kS.bleed then
lS.bleed=true
end
if(kS.amp or 0)>0 then
lS.amp=db.r3(kS.amp)
end
if kS.full then
lS.full=true
end
if kS.wholeMap then
lS.wholeMap=true
end
if kS.breakShields then
lS.breakShields=true
end
if kS.ally then
lS.allyBuff=kS.ally.types
lS.allyTime=kS.ally.time
end
if kS.allyCd then
lS.allyCd=kS.allyCd
end
if kS.allyRange then
lS.allyRange=kS.allyRange
end
if kS.selfDmg then
lS.selfDmg=kS.selfDmg
end
if kS.baseSafe then
lS.baseSafe=kS.baseSafe
