function kb.relicWorth(Dab,Eab)
local Fab=Eab._unique_item_data and Eab._unique_item_data._unique_relic_data
if not Fab then
return 0
end
local Gab=N.Items[Eab.item_id]or{}
local Hab,Iab=V.types(Dab.unit_id)
if Gab.main_damage_type and Gab.main_damage_type~=VBe[3208]and Gab.main_damage_type~=Iab then
return 0
end
local Jab,Kab=0,0
for Lab,Mab in pairs(Fab._core_damage_type_buffs or{})do
if Hab[Mab.damage_type]then
Jab=Jab+(tonumber(Mab.mul)or 0)+(tonumber(Mab.add_upg)or 0)*0.01+(tonumber(Mab.pen)or 0)*0.001
Kab=Kab+(tonumber(Mab.crit)or 0)
end
end
