local Nab=V.rows(Dab.unit_id)
local Oab=Nab and Nab[Nab.max]
local Pab=(Oab and tonumber(Oab.cd)or 0)*V.mult(Dab,VBe[2612])
for Qab,Rab in pairs(Fab._unique_relic_effects or{})do
local Sab=type(Rab.params)==VBe[2169]and Rab.params or{}
if Rab.id==VBe[3209]then
local Uab=math.min(1,(tonumber(Sab.extra_damage)or 0)*Pab/math.max(1,tonumber(Sab.time_interval)or 40))
local Vab=V.DRONES and V.DRONES[Dab.unit_id]
if Vab and Vab.late and Pab>0 then
local Wab=1/Pab
Uab=Uab*Wab/(Wab+(tonumber(Vab.max)or 0)*(tonumber(Vab.late.dmg)or 0)*(tonumber(Vab.hits)or 1)/math.max(0.1,tonumber(Vab.late.cd)or 4))
end
Jab=Jab+Uab
elseif Rab.id==VBe[3210]then
Jab=Jab+(tonumber(Sab.dmg_buff)or 0)*0.25
elseif Rab.id==VBe[3211]then
Jab=Jab+(tonumber(Sab.dmg_buff)or 0)*Kab
elseif Rab.id==VBe[3212]then
if Hab.magic then
Jab=0
else
Jab=Jab+(tonumber(Sab.dmg_buff)or 0)*0.3
end
elseif Rab.id==VBe[3213]then
if Hab.water_damage then
Jab=Jab+0.05
end
elseif Rab.id==VBe[2312]then
local Xab=tonumber(Sab.duration_buff)or tonumber(type(Rab.static_params)==VBe[2169]and Rab.static_params.duration_buff)or 2
local Yab,Zab=pcall(V.attackInfo,Oab and Oab.atk,Oab and Oab.range)
local _ab,abb=Yab and tonumber(Zab.burn)or 0,Yab and tonumber(Zab.dot)or 0
if _ab<=0 then
local bbb,cbb=pcall(pb.model,Dab.unit_id,Yab and Zab or nil,Oab)
if bbb and type(cbb)==VBe[2169]and(tonumber(cbb.burnDot)or 0)>0 then
_ab,abb=cbb.burnDot,abb+(tonumber(cbb.dot)or 0)
end
end
Jab=Jab+_ab*math.max(0,Xab-1)/(1+abb)
end
end
return Jab
end
