function kb.feedPlan(Wdb)
local Xdb=V.trait(Wdb)
local Ydb=Xdb==VBe[3232]and 1.5 or 1
local Zdb=math.max(0,kb.xpFor(Wdb.unit_id,kb.cap(Wdb))-(tonumber(Wdb.xp)or 0))
local _db,aeb,beb={},0,0
for ceb,deb in ipairs(kb.foodHeld())do
local eeb=deb.xp*Ydb
local feb=math.min(deb.n,math.floor((Zdb-aeb)/math.max(1,eeb)))
if feb>0 then
_db[deb.id]=feb
aeb=aeb+feb*eeb
beb=beb+feb
end
end
return{feed=_db,planned=aeb,n=beb}
end
function kb.run(geb)
local heb=N.session()
local ieb=heb and heb.collection:get_unit_by_uuid(geb.uuid)
if not ieb then
return
end
if geb.kind==VBe[3226]then
local jeb=kb.feedPlan(ieb)
local keb,leb,meb=jeb.feed,jeb.planned,jeb.n
if meb==0 then
P.str.feedNote=geb.name..VBe[3233]
return
end
local neb,oeb=tonumber(ieb.xp)or 0,kb.level(ieb)
local peb,qeb=F.request(VBe[3226],VBe[3234],geb.uuid,keb)
local reb=U.now()
while U.now()-reb<4 and(tonumber((heb.collection:get_unit_by_uuid(geb.uuid)or ieb).xp)or 0)<=neb do
task.wait(0.25)
end
local seb=heb.collection:get_unit_by_uuid(geb.uuid)or ieb
local teb=(tonumber(seb.xp)or 0)-neb
if teb>0 then
local ueb=kb.level(seb)
local veb=ueb>oeb and string.format(VBe[3228],oeb,ueb)or string.format(VBe[3229],oeb)
cb.add(string.format(VBe[3235],meb,geb.name),meb,VBe[3236],string.format(VBe[3237],U.fmt(teb),veb))
kb.note(string.format(VBe[3238],geb.name,meb,U.fmt(teb),veb,math.abs(teb-leb)>leb*0.1 and string.format(VBe[3239],U.fmt(leb))or VBe[1088]))
else
kb.note(string.format(VBe[3240],geb.name,tostring(peb and qeb or VBe[2713])))
F.backoff(VBe[3226],600)
end
end
end
function kb.slotOf(web)
local xeb=N.session()
for yeb,zeb in pairs(xeb and xeb.profile_data.collection.equipped_units or{})do
if zeb==web then
return tonumber(yeb)or yeb
end
end
return nil
end
function kb.reequip()
local Aeb=P.str.reequip
if not Aeb then
return true
end
local Beb=N.session()
local Ceb=Beb and Beb.collection:get_unit_by_uuid(Aeb.uuid)
if not Ceb then
P.str.reequip=nil
return true
end
for Deb=1,3 do
if kb.slotOf(Aeb.uuid)then
break
end
F.request(VBe[3241],VBe[3242],Aeb.uuid)
local Eeb=U.now()
while U.now()-Eeb<3 and not kb.slotOf(Aeb.uuid)do
task.wait(0.25)
end
end
W._sigAt=nil
if kb.slotOf(Aeb.uuid)then
P.str.reequip=nil
F.saveSoon()
return true
end
F.log(1,VBe[3243],string.format(VBe[3244],V.name(Ceb.unit_id),tostring(Aeb.slot)))
return false
end
kb.REMOTE={feed=VBe[3226]}
kb.WORK_MAX=300
function kb.nextAct(Feb)
local Geb=os.time()
for Heb,Ieb in ipairs(Feb or{})do
local Jeb=F.req.back[kb.REMOTE[Ieb.kind]or VBe[1088]]
if not Ieb.blocked and not(Jeb and U.now()<Jeb)and(tonumber(P.str.noWork[Ieb.kind])or 0)<=Geb and(tonumber(P.str.noWork[Ieb.kind..VBe[2313]..tostring(Ieb.uuid)])or 0)<=Geb then
return Ieb
end
end
end
function kb.workSig()
local Keb=0
for Leb,Meb in ipairs(kb.foodHeld())do
Keb=Keb+Meb.n
end
return tostring(Keb)
end
kb.FEED_STOP_GAIN=0.5
function kb.focusReady()
if not(O.autoEvolve and O.evolveUnit~=VBe[1088])then
return nil
end
pcall(hb.refresh)
for Neb,Oeb in ipairs(P.goals or{})do
if Oeb.pinned and Oeb.uuid==O.evolveUnit and Oeb.ready and(ab.evoBlocked[Oeb.uuid]or 0)<os.time()then
local Peb={}
for Qeb,Reb in ipairs(V.equipped())do
Peb[Reb.uuid]=true
end
if not ab.evoEats(Oeb,Peb)then
return Oeb
end
end
end
end
function kb.hasWork(Seb)
if not Seb then
local Teb=kb.focusReady()
if Teb then
return VBe[3245]..V.name(Teb.from)..VBe[3246],VBe[2274]
end
for Ueb,Veb in ipairs(P.goals or{})do
local Web=Veb.pinned and ab.evolveBuyPlan(Veb)
if Web then
return VBe[3247]..((N.Items[Web.item]or{}).name or Web.item)..VBe[3248]..V.name(Veb.from)..VBe[3246],VBe[2274]
end
end
if ab.snipeWanted()then
return VBe[3249]..V.name(O.snipeUnit)..VBe[3250],VBe[3251]
end
if ab.snipeDue()then
return VBe[3252]..V.name(O.snipeUnit)..VBe[3253],VBe[3251]
end
if P.ownSwap then
return VBe[3254]..V.name(P.ownSwap.into)..VBe[3255],VBe[3256]
end
end
if not O.team or O.strDry then
return nil
end
kb.acts=kb.plan()
ab.last.teamPlan=U.now()
local Xeb=kb.acts
if not Seb then
Xeb={}
for Yeb,Zeb in ipairs(kb.acts)do
if not(Zeb.kind==VBe[3226]and(tonumber(Zeb.gain)or 0)<kb.FEED_STOP_GAIN)then
table.insert(Xeb,Zeb)
end
end
end
local _eb=kb.nextAct(Xeb)
if _eb then
return _eb.text,_eb.kind
end
if O.teamRelics and(tonumber(P.str.noWork.relic)or 0)<=os.time()and(not Seb or not(O.autoTeam and O.play))then
local afb,bfb=kb.relicPlan()
if bfb and bfb>=(Seb and kb.relicBar()or kb.RELIC_STOP_GAIN)then
return string.format(VBe[3257],bfb),VBe[3258]
end
end
if not Seb and O.teamXp and O.teamBuyXp and O.goldShop and os.time()-(tonumber(P.str.shopAt)or 0)>21600 and kb.xpRoom()>0 and(tonumber(N.cur(VBe[2241]))or 0)>(O.xpGoldFloor or 100000)then
return VBe[3259],VBe[3260]
end
return nil
end
function kb.finishWork()
local cfb=U.now()
local dfb=0
while F.alive and O.master and not P.holdLobby and not P.pauseAll and U.now()-cfb<kb.WORK_MAX do
local efb,ffb=kb.hasWork(true)
if not efb then
break
end
F.status(VBe[3261],VBe[3262]..tostring(efb))
if ffb==VBe[3258]then
local gfb,hfb=pcall(kb.relicsApply,true)
if not(gfb and hfb)then
P.str.noWork.relic=os.time()+1800
end
else
kb.tick()
end
dfb=dfb+1
task.wait(4)
end
if dfb>0 then
F.log(1,kb.LOG,string.format(VBe[3263],dfb,math.floor(U.now()-cfb)))
W._sigAt,W.lastScored=nil,nil
F.saveSoon()
end
end
function kb.tick()
if not O.team then
P.str.next=VBe[3264]
return
end
if P.str.reequip then
kb.reequip()
end
local ifb
if ab.every(VBe[3265],60)or not P.str.acts then
ifb=kb.plan()
else
ifb=kb.acts
end
kb.acts=ifb or kb.acts or{}
local jfb=kb.nextAct(kb.acts)
if not jfb then
local kfb=kb.acts[1]
P.str.next=kfb and(kfb.text..VBe[3266]..tostring(kfb.blocked))or VBe[3267]
return
end
if O.strDry then
P.str.next=VBe[3268]..jfb.text..VBe[3269]
if P.str.dryLast~=jfb.text then
P.str.dryLast=jfb.text
F.log(1,kb.LOG,VBe[3270]..jfb.text)
end
return
end
P.str.next=jfb.text
local lfb=kb.workSig()
local mfb,nfb=pcall(kb.run,jfb)
if not mfb then
F.log(1,VBe[2178],VBe[3271]..tostring(nfb))
end
if kb.workSig()==lfb then
P.str.noWork[jfb.kind..VBe[2313]..tostring(jfb.uuid)]=os.time()+1800
end
local ofb=F.req.back[kb.REMOTE[jfb.kind]or VBe[1088]]
if ofb and ofb>U.now()then
P.str.noWork[jfb.kind]=os.time()+math.ceil(ofb-U.now())
end
ab.last.teamPlan=nil
end
function kb.rows()
local pfb=N.session()
local qfb={}
if not pfb then
return qfb
end
for rfb,sfb in ipairs(P.str.core or{})do
local tfb=pfb.collection:get_unit_by_uuid(sfb)
if tfb then
local ufb,vfb=V.trait(tfb)
local wfb={string.format(VBe[3272],kb.level(tfb),kb.cap(tfb)),kb.traitName(ufb,vfb)}
if tfb.trait_stats then
table.insert(wfb,(ab.statRanks(tfb):gsub(VBe[2552],VBe[3273])))
end
table.insert(wfb,V.relicName(tfb)and(VBe[3274]..V.relicName(tfb))or VBe[3275])
if kb.lb(tfb)>=1 then
table.insert(wfb,VBe[3276])
end
local xfb
for yfb,zfb in ipairs(P.str.acts or{})do
if zfb.uuid==sfb then
xfb=zfb
break
end
end
if xfb then
table.insert(wfb,VBe[3277]..(xfb.text:gsub(VBe[3278],string.upper))..(xfb.blocked and(VBe[3279]..xfb.blocked..VBe[2840])or VBe[1088]))
end
table.insert(qfb,{name=V.name(tfb.unit_id),text=table.concat(wfb,VBe[2552])})
end
end
return qfb
end
function kb.text()
if not O.team then
return VBe[3280]
end
local Afb={P.str.next or VBe[3281]}
if P.str.relicNote then
table.insert(Afb,VBe[3282]..P.str.relicNote)
end
for Bfb=1,math.min(4,#(P.str.log or{}))do
table.insert(Afb,os.date(VBe[3283],P.str.log[Bfb].at)..VBe[2180]..P.str.log[Bfb].msg)
end
return table.concat(Afb,VBe[2184])
end
ab.last={}
ab.hatched={}
function ab.evolve(Cfb,Dfb)
local Efb=N.session()
local Ffb=Efb.collection:get_unit_by_uuid(Cfb.uuid)
if not Ffb then
return false,VBe[3284]
end
local Gfb,Hfb=0,{}
for Ifb,Jfb in pairs(Efb.profile_data.collection.owned_units)do
if Jfb.unit_id==Cfb.to then
Gfb=Gfb+1
Hfb[Ifb]=true
end
end
local Kfb,Lfb=F.request(VBe[2274],VBe[3285],Cfb.uuid)
task.wait(2)
local Mfb=Efb.collection:get_unit_by_uuid(Cfb.uuid)
local Nfb=0
for Ofb,Pfb in pairs(Efb.profile_data.collection.owned_units)do
if Pfb.unit_id==Cfb.to then
Nfb=Nfb+1
if not Hfb[Ofb]then
if O.fuseXpUnit==Cfb.uuid then
O.fuseXpUnit,O.fuseXpId=Ofb,Cfb.to
F.saveSoon()
end
end
end
end
if Nfb>Gfb then
local Qfb={}
for Rfb,Sfb in ipairs(Cfb.items or{})do
table.insert(Qfb,string.format(VBe[3286],(N.Items[Sfb.id]or{}).name or Sfb.id,Sfb.amount))
end
for Tfb,Ufb in ipairs(Cfb.eats or{})do
table.insert(Qfb,string.format(VBe[3287],Ufb.amount,V.name(Ufb.id)))
end
local Vfb=string.format(VBe[3288],V.name(Cfb.from),V.name(Cfb.to),U.fmt(Cfb.scoreFrom or 0),U.fmt(Cfb.scoreTo or 0))
cb.add(VBe[3289]..Vfb,1,VBe[3290],(Dfb or VBe[3291])..(#Qfb>0 and(VBe[3292]..table.concat(Qfb,VBe[2290]))or VBe[1088]))
F.log(1,VBe[3293],Vfb..VBe[3294]..(Dfb or VBe[3291])..(#Qfb>0 and(VBe[3292]..table.concat(Qfb,VBe[2290]))or VBe[1088]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Cfb.to)..VBe[3295]
end
F.log(1,VBe[3293],VBe[3296]..V.name(Cfb.from)..VBe[2868]..tostring(Lfb)..VBe[3297]..tostring(Mfb and Mfb.unit_id))
return false,VBe[3298]..tostring(Lfb)..VBe[2840]
end
ab.evoBlocked={}
function ab.evoEats(Wfb,Xfb)
local Yfb=N.session()
local Zfb,_fb=pcall(V.score,Yfb.collection:get_unit_by_uuid(Wfb.uuid))
for agb,bgb in ipairs(Wfb.eats or{})do
for cgb,dgb in ipairs(hb.copies(bgb.id,bgb.shiny,Wfb.uuid))do
local egb=Yfb.collection:get_unit_by_uuid(dgb.uuid)or dgb
local fgb,ggb=pcall(V.score,egb)
if Xfb[dgb.uuid]or V.trait(egb)or(Zfb and fgb and ggb>=_fb)then
return string.format(VBe[3299],V.name(bgb.id))
end
end
end
end
ab.pickNote={}
function ab.pickDone(hgb,igb,jgb,kgb)
O[hgb]=false
pcall(function()
nb.UI[hgb].Set(false,true)
end)
ab.pickNote[hgb]=jgb
F.log(1,VBe[2683],igb..VBe[2519]..jgb)
if F.notify then
F.notify(igb,jgb,kgb or VBe[3113])
end
F.saveSoon()
end
function ab.focusNextUp()
if O.focusNext==VBe[1088]or nb.focusNow()~=VBe[1088]then
return
end
local lgb=O.focusNext
local mgb=N.session()
local ngb,ogb
for pgb,qgb in pairs(mgb.profile_data.collection.owned_units)do
if qgb.unit_id==lgb and(not ngb or(tonumber(qgb.xp)or 0)>ogb)then
ngb,ogb=pgb,tonumber(qgb.xp)or 0
end
end
if not ngb then
O.focusNext=VBe[1088]
F.log(1,VBe[2683],VBe[3300]..V.name(lgb)..VBe[3301])
return F.saveSoon()
end
O.focusDone=O.evolveUnit
F.log(1,VBe[2683],VBe[3302]..V.name(lgb))
ab.setFocus(ngb)
nb.focusSig=nil
if F.notify then
F.notify(VBe[3303],VBe[3304]..V.name(lgb),VBe[3113])
end
end
function ab.evolveBuyPlan(rgb)
if not(O.autoEvolve and rgb and rgb.pinned and not rgb.ready and rgb.uuid==O.evolveUnit)then
return nil
end
for sgb,tgb in ipairs(rgb.plans or{})do
if tgb.eventShop and(tonumber(tgb.cost)or 0)>0 and tgb.currency and hb.have(tgb.item)<(tonumber(tgb.need)or 1)and(tonumber(N.cur(tgb.currency))or 0)>=tgb.cost then
return tgb
end
end
return nil
end
function ab.evolveBuy(ugb)
local vgb=ab.evolveBuyPlan(ugb)
if not vgb or F.where~=VBe[2246]then
return false
end
if F.req.back.evobuy and U.now()<F.req.back.evobuy then
return false
end
local wgb=(N.Items[vgb.item]or{}).name or vgb.item
local xgb=hb.have(vgb.item)
local ygb,zgb=F.request(VBe[3305],VBe[2788],vgb.item,VBe[2192],VBe[2789],VBe[2615])
local Agb=U.now()
while U.now()-Agb<4 and hb.have(vgb.item)<=xgb do
task.wait(0.25)
end
if hb.have(vgb.item)>xgb then
cb.add(wgb,vgb.cost,tostring(vgb.currency),VBe[3306]..V.name(ugb.from)..VBe[3307])
if F.notify then
F.notify(VBe[3303],VBe[3111]..wgb..VBe[3248]..V.name(ugb.from),VBe[3113])
end
pcall(hb.refresh)
return true
end
F.log(1,VBe[3114],string.format(VBe[3308],wgb,tostring(ygb and zgb or VBe[2713])))
F.backoff(VBe[3305],900)
return false
end
function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==VBe[1088]then
return
end
local Bgb=N.session()
if not(Bgb and Bgb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(VBe[3309],VBe[3303],VBe[3310],VBe[3311])
end
local Cgb
for Dgb,Egb in ipairs(P.goals or{})do
if Egb.pinned and Egb.uuid==O.evolveUnit then
Cgb=Egb
break
end
end
if not Cgb then
local Fgb=Bgb.collection:get_unit_by_uuid(O.evolveUnit)
local Ggb=N.Units[Fgb.unit_id]
if not(Ggb and Ggb.evolve and Ggb.evolve.evolve_unit)then
ab.pickDone(VBe[3309],VBe[3303],V.name(Fgb.unit_id)..VBe[3312],VBe[3311])
end
return
end
ab.pickNote.autoEvolve=nil
if not Cgb.ready and ab.evolveBuy(Cgb)then
for Hgb,Igb in ipairs(P.goals or{})do
if Igb.pinned and Igb.uuid==O.evolveUnit then
Cgb=Igb
break
end
end
end
if not Cgb.ready then
return
end
local Jgb={}
for Kgb,Lgb in ipairs(V.equipped())do
Jgb[Lgb.uuid]=true
end
local Mgb=ab.evoEats(Cgb,Jgb)
if Mgb then
ab.pickNote.autoEvolve=Mgb
return
end
if(ab.evoBlocked[Cgb.uuid]or 0)>=os.time()then
return
end
local Ngb,Ogb=ab.evolve(Cgb,VBe[3313])
if Ngb then
ab.pickDone(VBe[3309],VBe[3303],Ogb)
else
ab.evoBlocked[Cgb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=Ogb
end
end
function ab.evolveText()
if O.evolveUnit==VBe[1088]then
return VBe[3314]
end
local Pgb=ab.pickNote.autoEvolve and(VBe[2184]..ab.pickNote.autoEvolve)or VBe[1088]
if not O.autoEvolve then
return VBe[3315]..Pgb
end
for Qgb,Rgb in ipairs(P.goals or{})do
if Rgb.pinned and Rgb.uuid==O.evolveUnit then
return Rgb.text..((W.onlyOn()and not Rgb.ready)and(VBe[3316]..W.onlyText()..VBe[3317])or VBe[1088])..Pgb
end
end
return VBe[3318]..Pgb
end
ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(Sgb)
local Tgb=N.session()
local Ugb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local Vgb={[Sgb.uuid]=true,[O.evolveUnit]=true}
for Wgb,Xgb in ipairs(V.equipped())do
Vgb[Xgb.uuid]=true
end
for Ygb,Zgb in ipairs(P.savedTeam or{})do
Vgb[Zgb]=true
end
for _gb,ahb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Vgb[ahb]=true
end
local bhb={}
local function chb(dhb)
local ehb=dhb and N.Units[dhb.unit_id]
local fhb=ehb and ehb.evolve and(dhb.shiny and ehb.evolve.shiny or ehb.evolve.normal)
for ghb,hhb in pairs(type(fhb)==VBe[2169]and type(fhb.unit_requirement)==VBe[2169]and fhb.unit_requirement or{})do
if type(hhb)==VBe[2169]and hhb.unit_id then
bhb[hhb.unit_id]=math.max(bhb[hhb.unit_id]or 0,tonumber(hhb.amount)or 1)
end
end
end
pcall(chb,Sgb)
pcall(function()
chb(Tgb.collection:get_unit_by_uuid(O.evolveUnit))
end)
local ihb,jhb={},0
for khb,lhb in pairs(Tgb.profile_data.collection.owned_units)do
local mhb=N.Units[lhb.unit_id]
local nhb=mhb and ab.FUSE_RANK[mhb.rarity]
if nhb and nhb<=Ugb and not Vgb[khb]and(bhb[lhb.unit_id]or 0)>0 then
bhb[lhb.unit_id]=bhb[lhb.unit_id]-1
nhb=nil
end
if nhb and nhb<=Ugb and not Vgb[khb]then
local ohb=Tgb.collection:get_unit_by_uuid(khb)or lhb
if not(lhb._locked or ohb._locked)and not(lhb._equipped_relic or ohb._equipped_relic)then
local phb,qhb=pcall(N.USC.calculate_xp_gain_from_fuse,Sgb,{ohb},Tgb)
qhb=phb and tonumber(qhb)or 0
if qhb>0 then
table.insert(ihb,{uuid=khb,id=lhb.unit_id,xp=qhb,rarity=mhb.rarity})
jhb=jhb+qhb
end
end
end
end
table.sort(ihb,function(rhb,shb)
if rhb.xp~=shb.xp then
return rhb.xp<shb.xp
end
return rhb.uuid<shb.uuid
end)
local thb=math.max(0,kb.xpFor(Sgb.unit_id,kb.cap(Sgb))-(tonumber(Sgb.xp)or 0))
local uhb,vhb={},0
for whb,xhb in ipairs(ihb)do
if vhb>=thb then
break
end
table.insert(uhb,xhb)
vhb=vhb+xhb.xp
end
return uhb,vhb,thb,jhb
end
function ab.fuseXpTarget(yhb)
local zhb=yhb and yhb.collection:get_unit_by_uuid(O.fuseXpUnit)
if zhb then
if O.fuseXpId~=zhb.unit_id then
O.fuseXpId=zhb.unit_id
F.saveSoon()
end
return zhb
end
local Ahb=yhb and N.Units[O.fuseXpId]
local Bhb=Ahb and Ahb.evolve and Ahb.evolve.evolve_unit
local Chb,Dhb
for Ehb,Fhb in pairs(Bhb and yhb.profile_data.collection.owned_units or{})do
if Fhb.unit_id==Bhb and(not Chb or(tonumber(Fhb.xp)or 0)>Dhb)then
Chb,Dhb=Ehb,tonumber(Fhb.xp)or 0
end
end
if not Chb then
return nil
end
F.log(1,VBe[2683],string.format(VBe[3319],V.name(O.fuseXpId),V.name(Bhb)))
O.fuseXpUnit,O.fuseXpId=Chb,Bhb
F.saveSoon()
return yhb.collection:get_unit_by_uuid(Chb)
end
function ab.fuseXpText()
if O.fuseXpUnit==VBe[1088]then
return VBe[3320]
end
local Ghb=N.session()
local Hhb=ab.fuseXpTarget(Ghb)
if not Hhb then
return VBe[3321]
end
local Ihb,Jhb,Khb=ab.xpFodder(Hhb)
