local Gmc,Hmc=0,0
for Imc,Jmc in ipairs(V.equipped())do
local Kmc=Jmc.id or(Jmc.u and Jmc.u.unit_id)
if Kmc and not V.isFarm(Kmc)then
Gmc=Gmc+1
local Lmc,Mmc=pcall(V.airFrom,Kmc)
if Lmc and Mmc then
Hmc=Hmc+(Mmc==0 and 1 or 0.5)
end
end
end
return 1+2*(Gmc>0 and 1-Hmc/Gmc or 0.5)
end
return jb.CURSE_COST[Fmc]or 1.5
end
function jb.roomValue(Nmc,Omc)
local Pmc,Qmc=Nmc.tags,Nmc.d
local Rmc=0
if Pmc[jb.T.GOLD]then
Rmc=Rmc+12
end
if Pmc[jb.T.CHEST]then
Rmc=Rmc+4
end
if Pmc[jb.T.MONEY]then
Rmc=Rmc+(Qmc<=15 and 2 or 0.5)
end
if Pmc[jb.T.SHOP]then
if Qmc>=10 and Qmc<=15 then
Rmc=Rmc+(Omc>=300 and 5 or 1)
else
Rmc=Rmc+(Omc>=300 and(Qmc>15 and 3 or 1)or 0.3)
end
end
if Pmc[jb.T.SHRINE]then
Rmc=Rmc+1.5
end
if Pmc[jb.T.CURSE]then
Rmc=Rmc-jb.curseCost(jb.roomCurse(Nmc.r))
end
return Rmc
end
function jb.mod(Smc)
local Tmc={weak={},strong={}}
for Umc,Vmc in pairs(type(Smc)==VBe[2169]and type(Smc._weak_against)==VBe[2169]and Smc._weak_against or{})do
if type(Vmc)==VBe[2169]and Vmc.damage_type then
Tmc.weak[Vmc.damage_type]=W.weakAmp(Vmc.amplification)
end
end
for Wmc,Xmc in pairs(type(Smc)==VBe[2169]and type(Smc._strong_against)==VBe[2169]and Smc._strong_against or{})do
Tmc.strong[type(Xmc)==VBe[2169]and Xmc.damage_type or Xmc]=true
end
return(next(Tmc.weak)or next(Tmc.strong))and Tmc or nil
end
function jb.roomCurse(Ymc)
local Zmc=type(Ymc)==VBe[2169]and type(Ymc._t)==VBe[2169]and Ymc._t or{}
local _mc=Zmc[0]or Zmc[VBe[4168]]
return type(_mc)==VBe[2169]and _mc.id or nil
end
function jb.fx(anc,bnc,cnc)
local dnc={dmg=1,cd=1,range=1,cost=1,hp=1,speed=1,regen=0,crit=0,kinds={},shield=0,fly=0}
local enc=jb.items(anc)
if bnc and jb.item(bnc)then
enc[bnc]=(enc[bnc]or 0)+1
end
if cnc and jb.item(cnc)then
enc[cnc]=(enc[cnc]or 0)+1
end
for fnc,gnc in pairs(enc)do
local hnc=jb.item(fnc)
for jnc,knc in pairs(type(hnc and hnc.wave_modifier_effects)==VBe[2169]and hnc.wave_modifier_effects or{})do
local lnc=(tonumber(knc.amount)or 0)*gnc
if knc.type==VBe[4157]and knc.stat==VBe[2611]then
dnc.dmg=dnc.dmg+lnc
elseif knc.type==VBe[4157]and knc.stat==VBe[2612]then
dnc.cd=dnc.cd+lnc
elseif knc.type==VBe[4157]and knc.stat==VBe[2429]then
dnc.range=dnc.range+lnc
elseif knc.type==VBe[4158]and tostring(knc.stat):sub(1,9)==VBe[4169]then
local mnc=tostring(knc.stat):sub(10)
dnc.kinds[mnc]=(dnc.kinds[mnc]or 0)+lnc
elseif knc.type==VBe[4162]and knc.stat==VBe[4163]then
dnc.crit=dnc.crit+lnc
elseif knc.type==VBe[4166]then
dnc.cost=dnc.cost+lnc
elseif knc.type==VBe[4170]and knc.stat==VBe[3716]then
dnc.hp=dnc.hp+lnc
elseif knc.type==VBe[4165]then
dnc.speed=dnc.speed+lnc
elseif knc.type==VBe[4171]then
dnc.regen=dnc.regen+lnc
elseif knc.type==VBe[4172]then
dnc.shield=dnc.shield+lnc
elseif knc.type==VBe[4173]and knc.passive==VBe[4174]then
dnc.fly=dnc.fly+lnc
elseif knc.type==VBe[4173]and knc.passive==VBe[4175]then
dnc.burst=(dnc.burst or 0)+lnc
end
end
end
dnc.cd,dnc.cost,dnc.speed=math.max(0.1,dnc.cd),math.max(0.1,dnc.cost),math.max(0.1,dnc.speed)
return dnc
end
function jb.fxText(nnc)
local onc={}
local function pnc(qnc,rnc)
if math.abs(rnc-1)>0.001 then
table.insert(onc,string.format(VBe[4037],qnc,rnc))
end
end
pnc(VBe[2611],nnc.dmg)
pnc(VBe[2948],nnc.cd)
pnc(VBe[2429],nnc.range)
pnc(VBe[4176],nnc.cost)
for snc,tnc in pairs(nnc.kinds)do
table.insert(onc,string.format(VBe[2698],snc,math.floor(tnc*100+0.5)))
end
if nnc.crit>0 then
table.insert(onc,string.format(VBe[4064],math.floor(nnc.crit*100+0.5)))
end
pnc(VBe[4177],nnc.hp)
pnc(VBe[4178],nnc.speed)
if nnc.regen>0 then
table.insert(onc,string.format(VBe[4179],math.floor(nnc.regen*100+0.5)))
end
if nnc.shield>0 then
table.insert(onc,string.format(VBe[4180],math.floor(nnc.shield+0.5)))
end
if nnc.fly>0 then
table.insert(onc,string.format(VBe[4181],math.floor(nnc.fly*100+0.5)))
end
if(nnc.burst or 0)>0 then
table.insert(onc,string.format(VBe[4182],math.floor(nnc.burst*100+0.5)))
end
return#onc>0 and table.concat(onc,VBe[2290])or VBe[2760]
end
function jb.sim(unc,vnc,wnc)
if not O.sim or type(unc.r._l)~=VBe[2169]then
return nil
end
local xnc=tostring(unc.r._r or(unc.d..VBe[2313]..unc.choice))..(vnc and(VBe[2491]..tostring(vnc))or VBe[1088])..(wnc and VBe[4183]or VBe[1088])
local ync=jb.data()
local znc=jb.fx(ync,jb.roomCurse(unc.r),vnc)
local Anc=W.teamSig()..VBe[2182]..jb.fxText(znc)..(O.killZone~=false and VBe[4184]or VBe[1088])..(bb.forcedWay()and(VBe[2182]..tostring(O.placeMode))or VBe[1088])
local Bnc=P.dg.sim[xnc]
if Bnc and Bnc.sig==Anc then
return not Bnc.none and Bnc or nil
end
local Cnc={}
for Dnc,Enc in ipairs(V.equipped())do
table.insert(Cnc,Enc.u)
end
if#Cnc==0 then
return nil
end
local Fnc=gb.applyFx(gb.info(gb.slim(unc.r._l),VBe[2898],nil,jb.mod(unc.r._l)),znc)
jb.applyK(Fnc,unc.r._r)
if wnc then
Fnc.zone=false
end
local Gnc=gb.wave(Fnc,1,true)
if#Gnc==0 then
Bnc={none=true,sig=Anc,at=os.time()}
else
local Hnc=gb.evaluate(Fnc,gb.teamFrom(Cnc,Fnc.map))
Bnc={p=Hnc.p,wave=Hnc.wave,won=Hnc.won,total=Fnc.total,margin=Hnc.margin,sig=Anc,at=os.time(),zone=Fnc.zone~=false or nil}
end
P.dg.sim[xnc]=Bnc
if U.count(P.dg.sim)>60 then
local Inc,Jnc
for Knc,Lnc in pairs(P.dg.sim)do
if not Jnc or(Lnc.at or 0)<Jnc then
Inc,Jnc=Knc,Lnc.at or 0
end
end
P.dg.sim[Inc]=nil
end
F.saveSoon()
return not Bnc.none and Bnc or nil
end
function jb.winP(Mnc)
local Nnc=tostring(math.min(4,math.max(1,math.ceil(Mnc.d/5))))
local Onc=P.dg.depth[Nnc]or{runs=0,wins=0}
local Pnc=U.clamp(0.95-0.015*Mnc.d,0.5,0.95)
local Qnc=((tonumber(Onc.wins)or 0)+Pnc*2)/((tonumber(Onc.runs)or 0)+2)
local Rnc,Snc=pcall(jb.sim,Mnc)
if Rnc and Snc and Snc.p then
local Tnc,Unc=pcall(gb.styleP,Snc,Snc.zone==false and VBe[4027]or(Snc.zone and VBe[3961]or nil))
Qnc=(Qnc*2+(Tnc and Unc or Snc.p))/3
end
return Qnc,Rnc and Snc or nil
end
function jb.hopeless(Vnc)
return Vnc~=nil and Vnc.won==false and(tonumber(Vnc.p)or 1)<=0.05
end
function jb.stake(Wnc)
local Xnc,Ync,Znc=jb.res(Wnc)
return Ync+2*Znc
end
function jb.curseBar(_nc,aoc)
local boc=jb.stake(_nc)
if aoc>=15 or boc>=8 then
return 0.9,VBe[4185],boc
end
if aoc>=10 or boc>=4 then
return 0.6,VBe[4186],boc
end
return 0.1,VBe[4187],boc
end
function jb.blindCurse(coc,doc)
return jb.fxText(jb.fx(coc,doc))==jb.fxText(jb.fx(coc))
end
function jb.curseOk(eoc,foc,goc,hoc,ioc)
local joc=tostring((jb.item(eoc)or{}).name or eoc)
local koc,loc,moc=jb.curseBar(foc,goc)
if koc>0.2 and jb.blindCurse(foc,eoc)then
return false,string.format(VBe[4188],joc,moc)
end
local function noc(ooc)
return ooc==nil or(tonumber(ooc.p)or 1)>=koc
end
if hoc then
local poc,qoc=pcall(jb.sim,hoc,nil,true)
if poc and not noc(qoc)then
return false,string.format(VBe[4189],joc,(loc:gsub(VBe[3792],VBe[4190])),tostring(qoc.margin or VBe[2412]))
end
end
if#ioc==0 then
return true
end
local roc
for soc,toc in ipairs(ioc)do
local uoc,voc=pcall(jb.sim,toc,eoc,true)
if not uoc or noc(voc)then
return true
end
if not roc or(tonumber(voc.p)or 0)>(tonumber(roc.p)or 0)then
roc=voc
end
end
return false,string.format(VBe[4191],joc,loc,tostring(roc and roc.margin or VBe[2412]))
end
function jb.curseGate(woc,xoc)
local yoc=jb.roomCurse(woc.r)
if not yoc then
return true
end
return jb.curseOk(yoc,xoc,woc.d,woc,jb.after(xoc,woc.choice))
end
function jb.payValue()
local zoc,Aoc=0,0
for Boc,Coc in ipairs(P.dg.pay or{})do
if type(Coc.items)==VBe[2169]then
local Doc=tonumber(Coc.gems)or 0
for Eoc,Foc in pairs(Coc.items)do
if(tonumber(Foc)or 0)>0 then
Doc=Doc+W.itemValue(Eoc,Foc)
end
end
zoc,Aoc=zoc+Doc,Aoc+1
end
end
if Aoc<5 then
return nil
end
return zoc/Aoc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local Goc=type(P.dg)==VBe[2169]and type(P.dg.lossCalls)==VBe[2169]and P.dg.lossCalls or{}
return U.clamp(((tonumber(Goc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(Goc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(Hoc)
local Ioc,Joc=jb.curses(Hoc),jb.lives(Hoc)
local Koc=jb.res(Hoc)
local Loc=jb.rooms(Hoc)
local Moc={}
for Noc,Ooc in ipairs(Loc)do
table.insert(Moc,tostring(Ooc.r._r))
end
local Poc=table.concat(Moc,VBe[3041])..string.format(VBe[4192],Joc,Koc,Ioc,W.teamSig())
if jb._pick and jb._pick.sig==Poc then
return jb._pick.x
end
local Qoc,Roc,Soc,Toc
for Uoc,Voc in ipairs(Loc)do
local Woc=jb.roomValue(Voc,Koc)
local Xoc,Yoc
for Zoc,_oc in ipairs(jb.after(Hoc,Voc.choice))do
local apc=jb.roomValue(_oc,Koc)
if not Xoc or apc>Xoc then
Xoc,Yoc=apc,_oc
end
end
local bpc,cpc=jb.winP(Voc)
local dpc=cpc~=nil and cpc.won==false
local epc=Joc>=3 and 1 or(Joc==2 and 2 or 6)
local fpc=1-(1-bpc)^math.max(1,Joc)
Voc.oldScore=fpc*(Woc+0.6*(Xoc or 0))-(1-bpc)*epc
if dpc then
bpc=math.min(bpc,jb.lossWin())
fpc=bpc
epc=epc*2
end
Voc.p,Voc.sim,Voc.value,Voc.nextValue,Voc.nextRoom,Voc.simLost=bpc,cpc,Woc,Xoc or 0,Yoc,dpc or nil
Voc.score=fpc*(Woc+0.6*(Xoc or 0))-(1-bpc)*epc
local gpc,hpc,ipc=pcall(jb.curseGate,Voc,Hoc)
if gpc and not hpc then
Voc.blocked=ipc
end
if not Voc.blocked then
if not Qoc or Voc.score>Qoc.score then
Qoc=Voc
end
if dpc then
if not Toc or Voc.score>Toc.score then
Toc=Voc
end
elseif not Soc or Voc.score>Soc.score then
Soc=Voc
end
end
if not Roc or Voc.score>Roc.score then
Roc=Voc
end
end
if Qoc and Qoc.simLost and Soc then
F.log(1,VBe[4193],string.format(VBe[4194],jb.roomName(Qoc),tostring(Qoc.sim and Qoc.sim.margin or VBe[2412]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Soc)))
elseif Qoc and Toc and Toc~=Qoc and Toc.oldScore>Qoc.score then
F.log(1,VBe[4193],string.format(VBe[4195],jb.roomName(Toc),tostring(Toc.sim and Toc.sim.margin or VBe[2412]),jb.roomName(Qoc)))
end
Qoc=Qoc or Roc
jb._pick={sig=Poc,x=Qoc,rooms=Loc}
return Qoc
end
