function jb.offers(Ipc,Jpc)
local Kpc={}
if type(Ipc)~=VBe[2169]then
return Kpc
end
for Lpc,Mpc in pairs(Ipc)do
local Npc,Opc
if type(Mpc)==VBe[2169]then
Npc=Mpc.id or Mpc.item_id or Mpc.item
Opc=tonumber(Mpc.cost)or tonumber(Mpc.price)
elseif type(Mpc)==VBe[1074]then
Npc=Mpc
elseif jb.item(Lpc)then
Npc=Lpc
Opc=tonumber(Mpc)
end
if type(Npc)==VBe[1074]and jb.item(Npc)then
table.insert(Kpc,{key=Lpc,id=Npc,cost=Opc or tonumber(jb.item(Npc).cost)or 0,bought=type(Mpc)==VBe[2169]and(Mpc.bought or Mpc.sold or Mpc.purchased)or nil})
end
end
if#Kpc==0 and not Jpc then
for Ppc,Qpc in pairs(Ipc)do
if type(Qpc)==VBe[2169]then
Kpc=jb.offers(Qpc,true)
if#Kpc>0 then
break
end
end
end
end
return Kpc
end
function jb.buy(Rpc)
local Spc=jb.res(jb.data())
local Tpc={}
if P.dg.buyArg==VBe[2554]then
Tpc={Rpc.id,Rpc.key}
else
Tpc={Rpc.key,Rpc.id}
end
if Tpc[1]==Tpc[2]then
Tpc[2]=nil
end
for Upc,Vpc in ipairs(Tpc)do
local Wpc,Xpc=F.request(VBe[4203],VBe[3818],Vpc)
local Ypc=U.now()
while U.now()-Ypc<3 and jb.res(jb.data())>=Spc do
task.wait(0.25)
end
if jb.res(jb.data())<Spc then
P.dg.buyArg=(Vpc==Rpc.id and Rpc.id~=Rpc.key)and VBe[2554]or VBe[4204]
return true
end
if not Wpc then
break
end
end
return false
end
function jb.shopAhead(Zpc)
