function jb.walletDiff(Qqc,Rqc)
local Sqc={}
if Rqc.gems~=Qqc.gems then
table.insert(Sqc,string.format(VBe[4222],Rqc.gems-Qqc.gems))
end
if Rqc.gold~=Qqc.gold then
table.insert(Sqc,string.format(VBe[4223],Rqc.gold-Qqc.gold))
end
for Tqc,Uqc in pairs(Rqc.items)do
if Uqc~=(Qqc.items[Tqc]or 0)then
table.insert(Sqc,string.format(VBe[4224],Uqc-(Qqc.items[Tqc]or 0),tostring(Tqc)))
end
end
for Vqc,Wqc in pairs(Rqc.units)do
if not Qqc.units[Vqc]then
table.insert(Sqc,VBe[4225]..V.name(Wqc))
end
end
if Rqc.unique~=Qqc.unique then
table.insert(Sqc,string.format(VBe[4226],Rqc.unique-Qqc.unique))
end
return#Sqc>0 and table.concat(Sqc,VBe[2290])or VBe[4227]
end
