jb.note(string.format(VBe[4228],crc,_qc,arc,jb.luck(Xqc)))
F.request(VBe[4215],VBe[4216])
return
end
local drc,erc,frc=0,0,0
local grc=tonumber(N.cur(VBe[2239]))or 0
