for irc=1,_qc+arc+4 do
local jrc,krc,lrc=jb.res(jb.data())
if krc+lrc<=0 or frc>=2 then
break
end
local mrc,nrc
if krc>0 then
mrc,nrc=F.request(VBe[4229],VBe[3821])
else
mrc,nrc=F.request(VBe[4229],VBe[3821],true)
end
if mrc and nrc~=nil then
F.log(1,VBe[4193],VBe[4230]..(type(nrc)==VBe[2169]and U.json(U.plain(nrc)):sub(1,300)or tostring(nrc)))
end
local orc=U.now()
while U.now()-orc<4 do
local prc,qrc,rrc=jb.res(jb.data())
if qrc<krc or rrc<lrc then
break
end
task.wait(0.25)
end
local trc,urc,vrc=jb.res(jb.data())
if urc<krc then
drc=drc+(krc-urc)
frc=0
elseif vrc<lrc then
erc=erc+(lrc-vrc)
frc=0
else
frc=frc+1
end
task.wait(1)
if urc<krc or vrc<lrc then
local wrc=jb.wallet()
local xrc=jb.walletDiff(hrc,wrc)
F.log(1,VBe[4193],(vrc<lrc and VBe[4231]or VBe[4230])..xrc)
P.dg.pay=P.dg.pay or{}
local yrc={}
for zrc,Arc in pairs(wrc.items)do
if Arc~=(hrc.items[zrc]or 0)then
yrc[zrc]=Arc-(hrc.items[zrc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=vrc<lrc,gems=wrc.gems-hrc.gems,luck=jb.luck(Xqc),paid=xrc,items=yrc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
hrc=wrc
end
end
jb.note(string.format(VBe[4232],drc,erc,Yqc and VBe[4233]or(brc<=1 and VBe[4234]or VBe[4235]),jb.luck(Xqc),(tonumber(N.cur(VBe[2239]))or 0)-grc))
local Brc,Crc,Drc=jb.res(jb.data())
if(Yqc or crc>=jb.ROOMS)and Crc+Drc>0 then
jb.note(string.format(VBe[4236],Crc,Drc))
W.rec(VBe[2898]).restUntil=os.time()+1800
return VBe[4237]
end
if not Yqc then
F.request(VBe[4215],VBe[4216])
end
end
