for HAc,IAc in ipairs(EAc)do
local JAc=IAc._stats
if not V.isFarm(JAc.id.Value)and JAc:FindFirstChild(VBe[2429])then
table.insert(GAc,{p=U.flat(IAc:GetPivot().Position),r=JAc.range.Value*(V.SUMMONER[JAc.id.Value]and V.SUMMONER[JAc.id.Value].reach or 1),air=bb.canAir(IAc)})
end
end
local KAc,LAc=0,0
if#GAc>0 then
for MAc,NAc in ipairs(bb.samples)do
if NAc.prog>LAc then
local OAc=U.flat(NAc.pos)
for PAc,QAc in ipairs(GAc)do
if(OAc-QAc.p).Magnitude<=QAc.r then
if NAc.prog>KAc then
KAc=NAc.prog
end
if QAc.air then
LAc=NAc.prog
break
end
end
end
end
end
