local TAc={}
for UAc,VAc in ipairs(bb.samples)do
local WAc=U.flat(VAc.pos)
for XAc,YAc in ipairs(GAc)do
if(WAc-YAc.p).Magnitude<=YAc.r then
local ZAc=tostring(VAc.lane)
TAc[ZAc]=(TAc[ZAc]or 0)+1
if VAc.prog>(RAc[ZAc]or 0)then
RAc[ZAc]=VAc.prog
end
break
end
end
end
local _Ac,aBc={},0
for bBc,cBc in pairs(SAc.by)do
_Ac[bBc]=(TAc[bBc]or 0)/math.max(1,cBc)
aBc=math.max(aBc,_Ac[bBc])
end
bb.laneW={}
for dBc,eBc in pairs(SAc.by)do
bb.laneW[dBc]=(SAc.avg/math.max(1,eBc))*(1+1.5*(aBc>0 and(1-_Ac[dBc]/aBc)or 0))
end
bb.laneFrac=_Ac
else
bb.laneW,bb.laneFrac=nil,nil
end
local fBc,gBc,hBc
if#GAc>0 then
for iBc,jBc in ipairs(FAc)do
local kBc=(bb.laneW and jBc.lane)and(RAc[tostring(jBc.lane)]or 0)or KAc
if jBc.hp>0 and jBc.prog>kBc+0.02 and jBc.prog>(fBc or 0)then
fBc,hBc=jBc.prog,bb.laneW and jBc.lane or nil
end
if jBc.hp>0 and jBc.fly and jBc.prog>LAc+0.02 then
gBc=true
end
end
end
local lBc= #GAc>0 and(bb.pressure or 0)>=KAc-0.08
return{covEnd=KAc,airEnd=LAc,leak=fBc,leakLane=hBc,covL=RAc,airLeak=gBc,push=lBc,units= #GAc}
end
