bb.probe.Size=Vector3 .new(jTc*2,2.5,jTc*2)
bb.probe.CFrame=CFrame.new(iTc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return iTc
end
