function bb.bookSave(cUc,dUc,eUc,fUc)
P.mapBook=type(P.mapBook)==VBe[2169]and P.mapBook or{}
local gUc={}
for hUc,iUc in pairs(eUc.spots or{})do
gUc[hUc]={math.floor(iUc.X*10+0.5)/10,math.floor(iUc.Y*10+0.5)/10,math.floor(iUc.Z*10+0.5)/10}
end
P.mapBook[dUc.key]={spots=gUc,style=dUc.base.style,hp=fUc.hp,n=fUc.n,kills=eUc.kills and math.floor(eUc.kills+0.5)or nil,wave=eUc.wave and math.floor(eUc.wave*10+0.5)/10 or nil,base=fUc.baseWave and math.floor(fUc.baseWave*10+0.5)/10 or nil,label=fUc.label,map=cUc.map,killScore=fUc.kills,at=os.time()}
local jUc={}
for kUc,lUc in pairs(P.mapBook)do
table.insert(jUc,{k=kUc,at=type(lUc)==VBe[2169]and tonumber(lUc.at)or 0})
end
if#jUc>bb.BOOK_MAX then
table.sort(jUc,function(mUc,nUc)
return mUc.at>nUc.at
end)
for oUc=bb.BOOK_MAX+1,#jUc do
P.mapBook[jUc[oUc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(pUc,qUc,rUc)
if type(pUc)~=VBe[2169]or pUc.ended then
return
end
pUc.ended=true
if rUc and qUc then
local sUc=bb.bookFor(qUc.info)
if sUc then
sUc.n=pUc.n
F.saveSoon()
elseif pUc.run>0 then
pcall(bb.bookSave,qUc.info,qUc,rUc,pUc)
end
end
if pUc.run>0 then
F.log(1,VBe[2932],bb.studyWords(pUc))
end
end
function bb.studyReport()
