bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(LUc,MUc)
local NUc=bb.bookKey(LUc)
P.layoutRec=type(P.layoutRec)==VBe[2169]and P.layoutRec or{}
local OUc=P.layoutRec[NUc]
if type(OUc)~=VBe[2169]then
if not MUc then
return nil
end
OUc={at=os.time()}
P.layoutRec[NUc]=OUc
if U.count(P.layoutRec)>80 then
local PUc,QUc
for RUc,SUc in pairs(P.layoutRec)do
local TUc=type(SUc)==VBe[2169]and tonumber(SUc.at)or 0
if not QUc or TUc<QUc then
PUc,QUc=RUc,TUc
end
end
P.layoutRec[PUc]=nil
end
end
return OUc
end
function bb.layoutAdd(UUc,VUc,WUc,XUc,YUc)
UUc.runs,UUc.wins=(tonumber(UUc.runs)or 0)+1,(tonumber(UUc.wins)or 0)+(VUc and 1 or 0)
UUc.sec,UUc.wave=type(UUc.sec)==VBe[2169]and UUc.sec or{},type(UUc.wave)==VBe[2169]and UUc.wave or{}
if VUc and tonumber(WUc)then
table.insert(UUc.sec,math.floor(WUc+0.5))
end
table.insert(UUc.wave,tonumber(XUc)or 0)
if tonumber(YUc)then
UUc.kills=type(UUc.kills)==VBe[2169]and UUc.kills or{}
table.insert(UUc.kills,math.floor(tonumber(YUc)))
while#UUc.kills>bb.LAYOUT_KEEP do
table.remove(UUc.kills,1)
end
end
while#UUc.sec>bb.LAYOUT_KEEP do
table.remove(UUc.sec,1)
end
while#UUc.wave>bb.LAYOUT_KEEP do
table.remove(UUc.wave,1)
end
end
function bb.layoutJudge(ZUc,_Uc,aVc,bVc,cVc)
cVc=cVc or VBe[4523]
local dVc,eVc=tonumber(ZUc and ZUc.runs)or 0,tonumber(_Uc and _Uc.runs)or 0
if dVc<1 or eVc<bb.LAYOUT_CONTROL then
return nil
end
if bVc and type(ZUc.kills)==VBe[2169]and type(_Uc.kills)==VBe[2169]and#ZUc.kills>=1 and#_Uc.kills>=bb.LAYOUT_CONTROL then
local fVc,gVc=bb.labMedian(ZUc.kills),bb.labMedian(_Uc.kills)
if fVc and gVc and fVc<gVc*0.97 and(#ZUc.kills>=2 or fVc<gVc*0.85)then
return string.format(VBe[4524],fVc,gVc,cVc)
end
return nil
end
local hVc,iVc=(tonumber(ZUc.wins)or 0)/dVc,(tonumber(_Uc.wins)or 0)/eVc
if not aVc and iVc>=0.5 then
if hVc+0.25<iVc and(dVc>=2 or(hVc==0 and iVc>=0.9 and eVc>=3))then
return string.format(VBe[4525],tonumber(ZUc.wins)or 0,dVc,dVc==1 and VBe[1088]or VBe[2015],tonumber(_Uc.wins)or 0,eVc,cVc)
end
local jVc,kVc=bb.labMedian(ZUc.sec),bb.labMedian(_Uc.sec)
if jVc and kVc and jVc>kVc*1.10 and(#ZUc.sec>=2 or jVc>kVc*1.25)then
return string.format(VBe[4526],math.floor(jVc/60),jVc%60,math.floor(kVc/60),kVc%60,cVc)
end
return nil
end
local lVc,mVc=bb.labMedian(ZUc.wave),bb.labMedian(_Uc.wave)
if lVc and mVc and lVc<mVc-math.max(1,mVc*0.03)and(dVc>=2 or lVc<mVc*0.85)then
return string.format(VBe[4527],lVc,mVc,cVc)
end
return nil
end
function bb.layoutResult(nVc,oVc)
local pVc=bb.info
local qVc=bb.layoutSrc
if not(pVc and qVc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not pVc.timeLimit then
return
end
local rVc=bb.wave()
local sVc=bb.layoutRecFor(pVc,true)
sVc.at=os.time()
local tVc=pVc.timeLimit~=nil
local uVc=pVc.killScore and true or nil
local vVc=uVc and(bb.killsEnd or bb.realKills())or nil
if qVc==VBe[4493]then
local wVc=bb.bookFor(pVc)
if not wVc then
return
end
wVc.real=type(wVc.real)==VBe[2169]and wVc.real or{}
bb.layoutAdd(wVc.real,nVc,oVc,rVc,vVc)
local xVc=wVc.aside==nil and bb.layoutJudge(wVc.real,sVc.own,tVc,uVc)or nil
if xVc then
wVc.aside={at=os.time(),why=xVc}
F.log(1,VBe[4423],string.format(VBe[4528],xVc))
end
elseif qVc==VBe[3858]then
sVc.hiveUnit=type(sVc.hiveUnit)==VBe[2169]and sVc.hiveUnit or{}
local yVc=sVc.hiveUnit
bb.layoutAdd(yVc,nVc,oVc,rVc,vVc)
local zVc=bb.bookFor(pVc)
local AVc=zVc and type(zVc.real)==VBe[2169]and(tonumber(zVc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local BVc=AVc and zVc.real or sVc.own
local CVc=bb.layoutJudge(yVc,BVc,tVc,uVc,AVc and VBe[4529]or nil)
if CVc then
yVc.aside,yVc.why=os.time(),CVc
F.log(1,VBe[4423],string.format(VBe[4530],CVc))
elseif(tonumber(yVc.runs)or 0)>=bb.HIVE_TRIALS then
local DVc=BVc and bb.layoutJudge(BVc,yVc,tVc,uVc,VBe[4531])
if DVc and zVc and type(bb.hiveUnitPlan)==VBe[2169]then
for EVc,FVc in pairs(bb.hiveUnitPlan)do
zVc.spots[EVc]=FVc
end
zVc.real={runs=yVc.runs,wins=yVc.wins,sec=yVc.sec,wave=yVc.wave,kills=yVc.kills}
zVc.hive,zVc.aside=os.time(),nil
sVc.hiveUnit=nil
F.log(1,VBe[4423],string.format(VBe[4532],DVc))
else
yVc.aside,yVc.why=os.time(),VBe[4533]
F.log(1,VBe[4423],VBe[4534])
end
end
else
sVc[qVc]=type(sVc[qVc])==VBe[2169]and sVc[qVc]or{}
local GVc=sVc[qVc]
bb.layoutAdd(GVc,nVc,oVc,rVc,vVc)
if qVc==VBe[3857]and GVc.aside==nil then
local HVc=bb.layoutJudge(GVc,sVc.own,tVc,uVc)
if HVc then
GVc.aside,GVc.why=os.time(),HVc
F.log(1,VBe[4423],string.format(VBe[4535],HVc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={VBe[4536],VBe[4537],VBe[4538],VBe[4539]}
function bb.controlSpot(IVc,JVc)
if not bb.killZone()then
return nil
end
local KVc=gb.holds
if not KVc(IVc.id)or V.toggleOf(IVc.id)then
return nil
end
local LVc,MVc,NVc,OVc=1,0,0,{}
local PVc=bb.hurtSamples()
for QVc,RVc in ipairs(bb.mine or{})do
local SVc=RVc._stats
local TVc=SVc.id.Value
if SVc:FindFirstChild(VBe[2429])and not V.isFarm(TVc)and not V.allyBuff(TVc)then
local UVc,VVc=U.flat(RVc:GetPivot().Position),SVc.range.Value
if KVc(TVc)and not V.toggleOf(TVc)then
NVc=NVc+1
table.insert(OVc,{p=UVc,r=VVc})
else
for WVc,XVc in ipairs(PVc)do
if(U.flat(XVc.pos)-UVc).Magnitude<=VVc then
LVc,MVc=math.min(LVc,XVc.prog),math.max(MVc,XVc.prog)
end
end
end
end
end
if MVc<=LVc then
LVc,MVc=0.75,0.98
end
local YVc=(JVc or NVc)+1
local ZVc=({LVc,MVc,(LVc+MVc)/2,LVc-(MVc-LVc)/2})[YVc]
if not ZVc then
return nil
end
local _Vc=V.range(IVc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local aWc={}
for bWc,cWc in ipairs(bb.cands)do
local dWc,eWc,fWc=U.flat(cWc),0,0
for gWc,hWc in ipairs(PVc)do
if(U.flat(hWc.pos)-dWc).Magnitude<=_Vc then
fWc=fWc+1
if math.abs(hWc.prog-ZVc)<=0.05 then
eWc=eWc+1
local iWc=U.flat(hWc.pos)
for jWc,kWc in ipairs(OVc)do
if(iWc-kWc.p).Magnitude<=kWc.r then
eWc=eWc-0.5
break
end
end
end
end
end
if eWc>0 then
table.insert(aWc,{pos=cWc,sc=eWc,cov=fWc})
end
if bWc%60==0 then
task.wait()
end
end
table.sort(aWc,function(lWc,mWc)
return lWc.sc>mWc.sc
end)
for nWc,oWc in ipairs(aWc)do
local pWc=bb.valid(oWc.pos,IVc.data)
if pWc then
F.log(1,VBe[4362],string.format(VBe[4540],V.name(IVc.id),bb.CONTROL_WORDS[YVc],math.floor(ZVc*100+0.5)))
return pWc,oWc.cov,ZVc
end
if nWc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(qWc)
local rWc,sWc=gb.holds(qWc.id)
if not rWc then
return nil
end
if V.killFed(qWc.id)then
return nil
end
local tWc,uWc={},0
for vWc,wWc in ipairs(bb.mine or{})do
local xWc=wWc._stats
local yWc=xWc.id.Value
if xWc:FindFirstChild(VBe[2429])and not V.isFarm(yWc)and not V.allyBuff(yWc)and yWc~=qWc.id then
local zWc,AWc=pcall(bb.liveDps,wWc,yWc)
AWc=zWc and tonumber(AWc)or 0
if AWc>0 then
table.insert(tWc,{p=U.flat(wWc:GetPivot().Position),r=xWc.range.Value,d=AWc})
uWc=uWc+AWc
end
end
end
if#tWc==0 or uWc<=0 then
return nil
end
local BWc=bb.hurtSamples()
local CWc={}
for DWc,EWc in ipairs(BWc)do
local FWc,GWc=U.flat(EWc.pos),0
for HWc,IWc in ipairs(tWc)do
if(FWc-IWc.p).Magnitude<=IWc.r then
GWc=GWc+IWc.d
end
end
CWc[DWc]=GWc/uWc
end
local JWc=V.range(qWc.u,math.min(tonumber(sWc)or 0,3,V.rows(qWc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local KWc,LWc,MWc
for NWc,OWc in ipairs(bb.cands)do
local PWc,QWc,RWc=U.flat(OWc),0,0
for SWc,TWc in ipairs(BWc)do
if(U.flat(TWc.pos)-PWc).Magnitude<=JWc then
QWc=QWc+CWc[SWc]
RWc=RWc+1
end
end
if QWc>0 and(not LWc or QWc>LWc)then
local UWc=bb.valid(OWc,qWc.data)
if UWc then
KWc,LWc,MWc=UWc,QWc,RWc
end
end
if NWc%40==0 then
task.wait()
end
end
if not KWc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[qWc.id]then
bb.holdSaid[qWc.id]=true
F.log(1,VBe[4362],string.format(VBe[4541],V.name(qWc.id)))
end
return KWc,MWc or 0
end
function bb.bestSpot(VWc,WWc,XWc)
if(VWc._grif or VWc.id==V.GRIF.egg)and not XWc and bb.grifOn()then
local YWc,ZWc,_Wc=pcall(bb.grifSpot,VWc)
if YWc and ZWc then
return ZWc,_Wc
end
if not YWc and ab.every(VBe[4542],30)then
F.log(1,VBe[2178],VBe[4543]..tostring(ZWc))
end
if VWc._grif then
return nil,0
end
end
if bb.hybridHill and not VWc._hillTry and type(VWc.data)==VBe[2169]and VWc.data.hybrid_placement and not VWc.data.hill_unit then
local aXc=setmetatable({data=bb.hillData(VWc.data),_hillTry=true},{__index=VWc})
local bXc,cXc,dXc=pcall(bb.bestSpot,aXc,WWc,XWc)
if bXc and cXc then
return cXc,dXc
end
end
if bb.focus and not WWc and not XWc and not V.allyBuff(VWc.id)then
local eXc,fXc=bb.focusSpot(VWc)
if eXc then
return eXc,fXc
end
end
if O.fishiFollow and not WWc and not XWc then
local gXc,hXc,iXc,jXc,kXc=pcall(bb.drownBoss)
if gXc and hXc and not iXc and kXc and kXc[VWc.id]then
local lXc,mXc,nXc=pcall(bb.drownSpot,VWc,hXc)
if lXc and mXc then
return mXc,nXc
end
end
end
if not WWc and not XWc and not(bb.depth and bb.depth.leak)then
local oXc,pXc,qXc=pcall(bb.controlSpot,VWc)
if oXc and pXc then
return pXc,qXc
end
local rXc,sXc,tXc=pcall(bb.holdSpot,VWc)
if rXc and sXc then
return sXc,tXc
end
end
local uXc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[VWc.id]and not WWc and not XWc then
local vXc=false
for wXc,xXc in ipairs(bb.mine or{})do
local yXc=xXc._stats:FindFirstChild(VBe[2553])
if yXc and yXc.Value==VWc.uuid then
vXc=true
break
end
end
if not vXc then
for zXc,AXc in ipairs(bb.layout[VWc.id])do
local BXc=bb.valid(AXc,VWc.data)
if BXc and bb.sandLine()>0 and bb.cover(BXc,V.range(VWc.u,V.rows(VWc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
BXc=nil
end
if BXc and uXc then
local CXc,DXc,EXc=false,U.flat(BXc),V.range(VWc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local FXc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for GXc,HXc in ipairs(bb.hurtSamples())do
if HXc.prog>=uXc+0.02 and(not FXc or tostring(HXc.lane)==FXc)and(U.flat(HXc.pos)-DXc).Magnitude<=EXc then
CXc=true
break
end
end
if not CXc then
BXc=nil
end
end
if BXc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[VWc.id]=BXc
return BXc,bb.cover(BXc,V.range(VWc.u,math.min(3,V.rows(VWc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local IXc=VWc.data
local JXc=bb.depth
local KXc,LXc=bb.hurtSamples(),bb.sandLine()
local MXc
if XWc then
MXc=1
for NXc,OXc in ipairs(bb.mine or{})do
local PXc=OXc._stats
if not V.isFarm(PXc.id.Value)and not(PXc:FindFirstChild(VBe[2553])and PXc.uuid.Value==VWc.uuid)then
local QXc,RXc=U.flat(OXc:GetPivot().Position),PXc.range.Value
for SXc,TXc in ipairs(KXc)do
if TXc.prog<MXc and(U.flat(TXc.pos)-QXc).Magnitude<=RXc then
MXc=TXc.prog
end
end
end
end
if V.ENTRY[VWc.id]or(bb.studyEntry and VWc.id==bb.trialId)then
MXc=math.min(MXc,LXc+0.1)
end
end
local UXc=(bb.info and tonumber(bb.info.rangeScale))or 1
local VXc=V.range(VWc.u,(JXc and JXc.leak)and 0 or math.min(3,V.rows(VWc.id).max))*UXc
local WXc=(bb.kind==VBe[2195]or bb.style==VBe[3961]or bb.style==VBe[3963])and not WWc and not(JXc and JXc.leak)and not V.isFarm(VWc.id)and V.range(VWc.u,V.rows(VWc.id).max)*UXc or nil
local XXc=V.allyBuff(VWc.id)
if bb.killZone()and not WWc and not XWc and not XXc and not(JXc and JXc.leak)and not V.isFarm(VWc.id)then
local YXc=WXc or VXc
local ZXc={}
for _Xc,aYc in ipairs(bb.mine or{})do
local bYc=aYc._stats
local cYc=bYc.id.Value
if not V.isFarm(cYc)and not V.allyBuff(cYc)and bYc:FindFirstChild(VBe[2429])then
table.insert(ZXc,{p=U.flat(aYc:GetPivot().Position),r=bYc.range.Value})
end
end
local dYc={}
for eYc,fYc in ipairs(KXc)do
local gYc=0
local hYc=U.flat(fYc.pos)
for iYc,jYc in ipairs(ZXc)do
if(hYc-jYc.p).Magnitude<=jYc.r then
gYc=gYc+1
end
end
dYc[eYc]=gYc
end
local kYc,lYc,mYc
local nYc=0
for oYc,pYc in ipairs(bb.cands)do
local qYc=bb.valid(pYc,IXc)
nYc=nYc+1
if nYc%40==0 then
task.wait()
end
if qYc then
local rYc,sYc,tYc=U.flat(qYc),0,0
for uYc,vYc in ipairs(KXc)do
if(U.flat(vYc.pos)-rYc).Magnitude<=YXc then
tYc=tYc+1
if vYc.prog>=0.6 then
sYc=sYc+(vYc.prog-0.5)*(1+dYc[uYc])
end
