function bb.grifEggGain(wcd,xcd)
local ycd=bb.grifS
if not(bb.grifOn()and ycd and not ycd.done and not ycd.off and bb.grifLong())then
return 0
end
local zcd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,zcd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local Acd=(bb.info and tonumber(bb.info.waveSec))or 20
local Bcd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Acd))
